def semear_grupos(apps, schema_editor):
    """Cria os grupos a partir do texto 'grupo' que as páginas já têm (ordem alfabética, como era exibido)."""
    Formulario = apps.get_model('pcp', 'Formulario')
    Pagina = apps.get_model('pcp', 'Pagina')
    GrupoPagina = apps.get_model('pcp', 'GrupoPagina')
    for f in Formulario.objects.all():
        nomes = sorted(set(Pagina.objects.filter(versao__formulario=f).exclude(grupo='').values_list('grupo', flat=True)))
        for i, nome in enumerate(nomes):
            GrupoPagina.objects.get_or_create(formulario=f, nome=nome, defaults={'ordem': i})


